products=[('Con lăn chăm sóc cơ','Nhóm công cụ dự kiến. Chất liệu, kích thước và hướng dẫn sử dụng sẽ được bổ sung khi có sản phẩm thực tế.','<rect x="65" y="40" width="170" height="80" rx="35" fill="#667c60"/><path d="M95 45V115M125 40V120M155 40V120M185 40V120M215 45V115" stroke="#9ba98a" stroke-width="3"/>'),('Bóng massage','Nhóm công cụ dự kiến. Cần lựa chọn độ cứng và cách sử dụng phù hợp với tư vấn chuyên môn.','<circle cx="150" cy="80" r="55" fill="#a98b5e"/><circle cx="135" cy="65" r="36" fill="none" stroke="#ccb690"/>'),('Dụng cụ hỗ trợ xoa bóp','Nhóm công cụ dự kiến. Công dụng, nguồn gốc và lưu ý an toàn cần được xác minh trước khi mở bán.','<path d="M70 110Q95 10 155 35Q200 10 230 55Q195 100 160 95Q110 145 70 110" fill="#748773"/><path d="M90 100Q140 50 210 55" fill="none" stroke="#b4bda6" stroke-width="3"/>')]
prods=''.join('<article class="card"><div class="product"><svg viewBox="0 0 300 160" role="img" aria-label="Minh họa loại công cụ, không phải ảnh sản phẩm thực tế">'+svg+'</svg></div><div class="card-body"><span class="status">DỰ KIẾN · CHƯA MỞ BÁN</span><h3>'+title+'</h3><p>'+desc+'</p><details><summary>Thông tin cần biết</summary><p>Hình minh họa danh mục. Chưa có mã sản phẩm, giá hoặc tồn kho được xác nhận. Website hiện chưa nhận thanh toán.</p></details></div></article>' for title,desc,svg in products)
body='''<main id="main"><div class="wrap"><div class="hero"><div class="reveal"><span class="eyebrow">HÒA XÁ, HÀ NỘI · MASSAGE TRỊ LIỆU</span><h1>Lắng nghe cơ thể.<br><em>Chăm sóc từ<br>điều căn bản.</em></h1><p>Tìm hiểu về giải cơ sâu, xoa bóp và cách chăm sóc cơ thể có cơ sở — cùng Massage trị liệu Tuấn Béo.</p><a class="button" href="#giai-co">Tìm hiểu giải cơ sâu <span>↗</span></a><a class="textlink" href="#lien-he">Đến với Tuấn Béo</a><p class="hero-note">THẤU HIỂU CƠ THỂ &nbsp; / &nbsp; TÔN TRỌNG SỰ KHÁC BIỆT</p></div><div class="hero-art reveal"><img src="/assets/body-illustration.svg" alt="Minh họa nghệ thuật cơ thể và lá cây; không phải sơ đồ huyệt" width="520" height="560" style="width:100%;height:auto"><div class="art-label">Chăm sóc bắt đầu từ việc hiểu đúng.<br><strong>Nhẹ nhàng trong tiếp cận. Thận trọng trong lựa chọn.</strong></div></div></div><div class="principles"><div><span class="number">01</span> Kiến thức có nguồn tham khảo</div><div><span class="number">02</span> Hiểu lợi ích và giới hạn</div><div><span class="number">03</span> Ưu tiên sự phù hợp, an toàn</div></div></div>
<section id="gioi-thieu"><div class="wrap two"><div><span class="eyebrow">VỀ TUẤN BÉO</span><h2>Một điểm đến.<br>Một khởi đầu cho<br>sự quan tâm đúng cách.</h2></div><div><p>Massage trị liệu Tuấn Béo được giới thiệu tại nhà 64, đội 1, thôn Thái Bình, Hòa Xá, Hà Nội.</p><p class="muted">Website là nơi tìm hiểu kiến thức nền tảng về chăm sóc cơ, tiếp cận thông tin cơ sở và khám phá nhóm công cụ hỗ trợ dự kiến.</p><p class="tiny">Địa chỉ theo thông tin chủ cơ sở cung cấp. Hồ sơ người thực hiện, dịch vụ, thời lượng và bảng giá sẽ được bổ sung sau khi xác nhận.</p><a class="textlink" href="#lien-he">Xem vị trí cơ sở ↗</a></div></div></section>
<section class="dark" id="giai-co"><div class="wrap"><div class="intro"><span class="eyebrow">HIỂU VỀ PHƯƠNG PHÁP</span><h2>Giải cơ sâu.<br>Đi từ hiểu đúng đến chọn đúng.</h2><p class="muted">Tên gọi chưa nói lên toàn bộ kỹ thuật. Điều cần làm rõ là cách tác động, mục tiêu chăm sóc và mức độ phù hợp với từng người.</p></div><div class="steps"><div class="step"><span class="number">01 /</span><h3>Góc nhìn truyền thống</h3><p>Xoa bóp bấm huyệt sử dụng các thủ pháp bàn tay, gắn với hệ thống lý luận Y học cổ truyền.</p></div><div class="step"><span class="number">02 /</span><h3>Góc nhìn mô mềm</h3><p>Massage mô sâu và giải phóng cân cơ là những thuật ngữ cần phân biệt; không tự động đồng nghĩa với xoa bóp bấm huyệt.</p></div><div class="step"><span class="number">03 /</span><h3>Góc nhìn cá nhân</h3><p>Tình trạng sức khỏe, mục tiêu và phản hồi của mỗi người là cơ sở để trao đổi với người có chuyên môn.</p></div></div><a class="button light" href="/hieu-dung-giai-co-sau.html">Đọc tổng quan phương pháp ↗</a></div></section>
<section><div class="wrap two"><div><span class="eyebrow">CHỌN ĐIỀU BẠN QUAN TÂM</span><h2>Cơ thể khác nhau.<br>Câu hỏi cũng khác nhau.</h2><p class="muted">Bắt đầu bằng những câu hỏi phù hợp với hoàn cảnh của bạn. Đây là thông tin định hướng trao đổi, không phải chẩn đoán.</p></div><div><div class="tabs" role="tablist" aria-label="Nhóm quan tâm"><button role="tab" id="tab-0" aria-controls="topic" aria-selected="true" data-topic="0">Ngồi làm việc nhiều</button><button role="tab" id="tab-1" aria-controls="topic" aria-selected="false" tabindex="-1" data-topic="1">Tuổi trung niên</button><button role="tab" id="tab-2" aria-controls="topic" aria-selected="false" tabindex="-1" data-topic="2">Người cao tuổi</button></div><div class="topic" id="topic" role="tabpanel" aria-labelledby="tab-0" tabindex="0"><h3>Hiểu cảm giác căng mỏi</h3><p>Hãy mô tả vị trí, thời điểm xuất hiện và những hoạt động làm khó chịu tăng lên. Cảm giác mỏi kéo dài cần được đánh giá, thay vì chỉ tìm cách tác động mạnh hơn.</p></div></div></div></section>
<section class="band" id="kien-thuc"><div class="wrap"><div class="section-head"><div><span class="eyebrow">THƯ VIỆN KIẾN THỨC</span><h2>Chăm sóc có hiểu biết.</h2></div><p class="muted">Đọc chậm. Hiểu kỹ. Lựa chọn phù hợp.</p></div><div class="grid">'''+cards+'''</div></div></section>
<section id="cong-cu"><div class="wrap"><div class="section-head"><div><span class="eyebrow">CÔNG CỤ ĐỒNG HÀNH</span><h2>Chăm sóc trong nhịp sống thường ngày.</h2></div></div><p class="muted">Danh mục định hướng đang được chuẩn bị. Sản phẩm thực tế, giá bán và hướng dẫn sẽ được công bố sau khi xác minh.</p><div class="grid">'''+prods+'''</div></div></section>
<section class="band"><div class="wrap two"><div><span class="eyebrow">NHỮNG ĐIỀU NÊN BIẾT</span><h2>Giải đáp trước<br>khi lựa chọn.</h2><p class="muted">Một cuộc trao đổi rõ ràng giúp bạn chủ động hơn trong việc chăm sóc sức khỏe.</p></div><div><details><summary>Giải cơ sâu có phải xoa bóp bấm huyệt?</summary><p>Không nên mặc nhiên đồng nhất. Cần hỏi cơ sở về kỹ thuật cụ thể, người thực hiện và phạm vi áp dụng. Xem bài tổng quan để phân biệt các cách gọi.</p></details><details><summary>Có phải càng đau thì càng hiệu quả?</summary><p>Không lấy mức đau làm thước đo hiệu quả. Hãy trao đổi về cảm giác của bạn và yêu cầu ngừng khi có biểu hiện bất thường.</p></details><details><summary>Ai cần trao đổi với nhân viên y tế trước?</summary><p>Người có bệnh nền, chấn thương, đang dùng thuốc, mang thai hoặc có nguy cơ tổn thương cần được đánh giá phù hợp. Không trì hoãn khám bệnh để thử massage.</p></details><details><summary>Có thể mua công cụ hoặc đặt lịch tại đây chưa?</summary><p>Chưa. Danh mục công cụ hiện là định hướng, chưa mở bán. Bạn có thể mở hồ sơ Google Maps để tìm đường và kiểm tra kênh liên hệ của cơ sở.</p></details></div></div></section>
<section id="lien-he"><div class="wrap two"><div><span class="eyebrow">TÌM ĐƯỜNG ĐẾN CƠ SỞ</span><h2>Ghé Tuấn Béo<br>tại Hòa Xá.</h2><div class="contactbox"><span class="eyebrow">ĐỊA CHỈ ĐƯỢC CUNG CẤP</span><address>Nhà 64, đội 1, thôn Thái Bình,<br>Hòa Xá, Hà Nội, Việt Nam</address><a class="button" href="'''+maps+'''" target="_blank" rel="noopener noreferrer">Mở Google Maps ↗</a><p class="tiny">Vui lòng kiểm tra giờ hoạt động và kênh liên hệ trên hồ sơ Maps trước khi đến.</p></div></div><div><img class="map-photo" src="/assets/ban-do-khuon-vien.webp" alt="Ảnh vệ tinh và vùng đo khuôn viên do chủ cơ sở cung cấp" width="1324" height="730" loading="lazy"><p class="tiny">Ảnh Google Earth do chủ cơ sở cung cấp. Ranh đo chỉ mang tính tham khảo; chưa xác minh pháp lý hoặc đối chiếu với điểm ghim Google Maps.</p><a class="textlink" href="/nguon-du-lieu.html">Xem nguồn thông tin và ảnh ↗</a></div></div></section></main>'''
