(p/'app.js').write_text('''const menu=document.querySelector('.menu'),links=document.querySelector('.navlinks');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));links.classList.toggle('open',open)});links?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');links.classList.remove('open')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&links?.classList.contains('open')){menu.setAttribute('aria-expanded','false');links.classList.remove('open');menu.focus()}});
const topics=[['Hiểu cảm giác căng mỏi','Hãy mô tả vị trí, thời điểm xuất hiện và những hoạt động làm khó chịu tăng lên. Cảm giác mỏi kéo dài cần được đánh giá, thay vì chỉ tìm cách tác động mạnh hơn.'],['Đặt mục tiêu chăm sóc thực tế','Bạn muốn dễ chịu hơn trong sinh hoạt hay đang gặp hạn chế vận động? Hãy trao đổi mục tiêu cùng bệnh nền và thuốc đang dùng để được tư vấn phù hợp.'],['Ưu tiên đánh giá trước khi tác động','Cần trao đổi về tình trạng xương khớp, bệnh nền và các thuốc đang sử dụng. Kỹ thuật mạnh không mặc nhiên phù hợp với người cao tuổi.']];const tabs=[...document.querySelectorAll('[data-topic]')];function select(t){tabs.forEach(b=>{const on=b===t;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});const data=topics[Number(t.dataset.topic)],panel=document.querySelector('#topic');panel.setAttribute('aria-labelledby',t.id);panel.querySelector('h3').textContent=data[0];panel.querySelector('p').textContent=data[1]}tabs.forEach((t,i)=>{t.addEventListener('click',()=>select(t));t.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();select(tabs[next]);tabs[next].focus()}})});
''')
sources='''<main id="main" class="article"><p class="eyebrow">MINH BẠCH THÔNG TIN</p><h1>Nguồn dữ liệu và phạm vi bản đầu</h1><h2>Thông tin cơ sở</h2><p>Tên cơ sở và địa chỉ do người dùng cung cấp ngày 16/10/2026. Link hồ sơ Google Maps đã được cung cấp, nhưng chưa đọc được nội dung hồ sơ bằng công cụ tra cứu. Chưa xác minh số điện thoại, giờ hoạt động, logo, hình ảnh dịch vụ, đánh giá, chứng chỉ và danh sách dịch vụ.</p><h2>Hình ảnh</h2><p>Hai ảnh vệ tinh Google Earth và tệp KML do người dùng cung cấp. Giữ nguyên nội dung và dòng ghi nguồn trên ảnh. Chưa có xác nhận ranh giới pháp lý hoặc sự trùng khớp với vị trí hồ sơ Google Maps. Chữ T trên website là ký hiệu trình bày tạm thời, không phải logo chính thức. Hình cơ thể và công cụ là minh họa thiết kế, không phải ảnh cơ sở hoặc sản phẩm thực tế.</p><h2>Nội dung sức khỏe</h2><p>Bài viết là tổng hợp biên tập, chưa được người phụ trách chuyên môn của cơ sở duyệt. Nội dung không xác nhận hiệu quả dịch vụ riêng của Tuấn Béo.</p><ul><li><a href="https://www.nccih.nih.gov/health/massage-therapy-what-you-need-to-know">NCCIH: Massage Therapy — What You Need To Know</a></li><li><a href="https://benhvienyhcthungyen.vn/quy-trinh-ky-thuat-xoa-bop-bam-huyet-c23178.html">Bệnh viện Y học cổ truyền Hưng Yên: Quy trình kỹ thuật xoa bóp bấm huyệt</a></li><li><a href="https://www.ttyttuky.com/quy-trinh-xoa-bop-bam-huyet/">Trung tâm Y tế Tứ Kỳ: Quy trình xoa bóp bấm huyệt</a></li></ul><h2>Giao dịch và dữ liệu cá nhân</h2><p>Website chưa nhận đơn hàng, thanh toán hay thông tin bệnh án. Liên kết Google Maps dẫn đến dịch vụ bên ngoài. Phông chữ được tải từ Google Fonts; không cài công cụ phân tích hay quảng cáo trong phiên bản này.</p></main>'''
